def solve(s):
    """Toggle letter case, or reverse a string containing no letters."""
    swapped = ""
    reversed_s = ""
    has_letter = False
    for c in s:
        swapped += c.swapcase()
        reversed_s = c + reversed_s
        if c.isalpha():
            has_letter = True
    if has_letter:
        return swapped
    return reversed_s

